'use strict';
const $=id=>document.getElementById(id),WORLD=1024,MAX_HEIGHT=8848.86,MAP_MAX_ZOOM=19,TERRAIN_MAX_ZOOM=15;
const state={height:10,duration:60,progress:0,showWater:true,depthColors:false,waterOpacity:1,showRelief:true,showContour:false,playing:false,ready:false,revision:0,world:null,areaCurve:null};
const tileCache=new Map(),inflight=new Map(),activeTiles=new Set();let lastFrame=0,lastPaint=0,animationId=null,selected=null,selectedSample=null,inspectionPopup=null,inspectionPin=null,paramTimer=null,statusTimer=null,cursorPoint=null,cursorFrame=null,inspectionContent=null,inspectionSheetOpen=false;
const wrap=v=>((v%1)+1)%1,format=n=>Number(n).toLocaleString('es-CL',{maximumFractionDigits:2});
function compactNumber(n){return n>=1e6?(n/1e6).toLocaleString('es-CL',{maximumFractionDigits:2})+' M':Math.round(n).toLocaleString('es-CL')}
function worldIndex(lon,lat){const x=Math.floor(wrap((lon+180)/360)*WORLD),y=Math.max(0,Math.min(WORLD-1,Math.floor((1-Math.asinh(Math.tan(Math.max(-85,Math.min(85,lat))*Math.PI/180))/Math.PI)/2*WORLD)));return y*WORLD+x}
function pixelWorldIndex(coords,x,y){const total=2**coords.z;const gx=Math.floor(wrap((coords.x+(x+.5)/256)/total)*WORLD),gy=Math.max(0,Math.min(WORLD-1,Math.floor((coords.y+(y+.5)/256)/total*WORLD)));return gy*WORLD+gx}
function neighbors(i,n,wrapX,visit){const x=i%n,y=i/n|0;if(x)visit(i-1);else if(wrapX)visit(i+n-1);if(x<n-1)visit(i+1);else if(wrapX)visit(i-n+1);if(y)visit(i-n);if(y<n-1)visit(i+n)}
function connectedOcean(dem,n,wrapX,seeds){let sea=new Uint8Array(n*n),queue=new Int32Array(n*n),a=0,b=0;for(const i of seeds)if(!sea[i]&&dem[i]<=0){sea[i]=1;queue[b++]=i}while(a<b){const i=queue[a++];neighbors(i,n,wrapX,j=>{if(!sea[j]&&dem[j]<=0){sea[j]=1;queue[b++]=j}})}return sea}
function flood(terrain,seas,n,height,wrapX,borders=[]){let distance=new Float32Array(n*n);distance.fill(-1);let q=new Int32Array(n*n),a=0,b=0;for(let i=0;i<seas.length;i++)if(seas[i]){distance[i]=0;q[b++]=i}for(const i of borders)if(distance[i]<0&&terrain[i]<height){distance[i]=1;q[b++]=i}while(a<b){const i=q[a++];neighbors(i,n,wrapX,j=>{if(distance[j]<0&&terrain[j]<height){distance[j]=distance[i]+1;q[b++]=j}})}return distance}
function notify(text,error=false,persistent=false){clearTimeout(statusTimer);$('status').textContent=text;$('status').classList.toggle('error',error);$('status').hidden=false;if(!persistent)statusTimer=setTimeout(()=>$('status').hidden=true,3500)}
function makeCanvas(size=256){const c=document.createElement('canvas');c.width=c.height=size;return c}
function image(src,signal){return new Promise((resolve,reject)=>{const img=new Image();let timer;const finish=(error)=>{clearTimeout(timer);img.onload=img.onerror=null;if(signal)signal.removeEventListener('abort',abort);if(error)reject(error);else resolve(img)};const abort=()=>{finish(new DOMException('Carga descartada','AbortError'));img.src=''};if(signal?.aborted){abort();return}if(signal)signal.addEventListener('abort',abort,{once:true});timer=setTimeout(()=>{finish(new Error('Tiempo de carga agotado'));img.src=''},18000);if(src.startsWith('https:'))img.crossOrigin='anonymous';img.onload=()=>finish();img.onerror=()=>finish(new Error('Imagen de elevación no disponible'));img.src=src})}
function decode(img,size){const c=makeCanvas(size),ctx=c.getContext('2d',{willReadFrequently:true});ctx.imageSmoothingEnabled=false;ctx.drawImage(img,0,0,size,size);const bytes=ctx.getImageData(0,0,size,size).data,dem=new Float32Array(size*size);for(let i=0;i<dem.length;i++)dem[i]=bytes[i*4]*256+bytes[i*4+1]+bytes[i*4+2]/256-32768;return dem}
// Fuente de elevación para la simulación y el relieve: Copernicus GLO-30 (vía Mapterhorn, piezas Terrarium
// de 512 px hasta zoom 12). ?relieve=aws vuelve a Mapzen/Tilezen Terrain Tiles solo para comparar.
const DEM_SOURCE=(()=>{try{return new URLSearchParams(location.search).get('relieve')==='aws'?'aws':'copernicus'}catch{return 'copernicus'}})();
document.documentElement.dataset.dem=DEM_SOURCE;
const copernicusImages=new Map();
function copernicusImage(z,x,y,signal){const key=z+'/'+x+'/'+y;if(copernicusImages.has(key))return copernicusImages.get(key);const task=image('https://tiles.mapterhorn.com/'+key+'.webp',signal);task.catch(()=>copernicusImages.delete(key));copernicusImages.set(key,task);while(copernicusImages.size>24)copernicusImages.delete(copernicusImages.keys().next().value);return task}
// Una pieza de 256 px en zoom z equivale a una de 512 px en z-1; sobre zoom 13 se amplía un recorte de la de zoom 12.
async function loadDem(c,signal){
  if(DEM_SOURCE!=='copernicus')return decode(await image('https://s3.amazonaws.com/elevation-tiles-prod/terrarium/'+c.z+'/'+c.x+'/'+c.y+'.png',signal),256);
  const zm=Math.min(c.z-1,12),d=c.z-zm,f=2**d,w=512/f,img=await copernicusImage(zm,Math.floor(c.x/f),Math.floor(c.y/f),signal);
  const canvas=makeCanvas(256),ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.imageSmoothingEnabled=false;
  ctx.drawImage(img,(c.x%f)*w,(c.y%f)*w,w,w,0,0,256,256);
  const bytes=ctx.getImageData(0,0,256,256).data,dem=new Float32Array(65536);for(let i=0;i<dem.length;i++)dem[i]=bytes[i*4]*256+bytes[i*4+1]+bytes[i*4+2]/256-32768;return dem;
}
function relief(dem,sea,n){const c=makeCanvas(n),ctx=c.getContext('2d'),im=ctx.createImageData(n,n);for(let i=0;i<dem.length;i++){const k=Math.min(1,Math.max(0,dem[i])/7000),shade=Math.max(-22,Math.min(24,(dem[Math.max(0,i-1)]-dem[Math.min(dem.length-1,i+1)])*.15));const rgb=sea[i]?[15,44,61]:[77+65*k+shade,99+46*k+shade,97+25*k+shade];for(let j=0;j<3;j++)im.data[i*4+j]=rgb[j];im.data[i*4+3]=255}ctx.putImageData(im,0,0);return c}
function recomputeWorld(){const w=state.world,bins=new Float64Array(35400);for(let i=0;i<w.spill.length;i++)if(!w.sea[i]&&w.spill[i]<MAX_HEIGHT){const bucket=Math.max(1,Math.min(bins.length-1,Math.ceil(w.spill[i]*4)));bins[bucket]+=w.rowArea[i/WORLD|0]}for(let i=1;i<bins.length;i++)bins[i]+=bins[i-1];state.areaCurve=bins}

function tileGlobalData(coords){const dem=new Float32Array(65536);for(let y=0;y<256;y++)for(let x=0;x<256;x++)dem[y*256+x]=state.world.dem[pixelWorldIndex(coords,x,y)];return dem}
function tileFromParent(parent,coords,parentCoords){const factor=2**(coords.z-parentCoords.z),ox=(coords.x%factor)*256/factor,oy=(coords.y%factor)*256/factor,dem=new Float32Array(65536);for(let y=0;y<256;y++)for(let x=0;x<256;x++)dem[y*256+x]=parent[Math.min(255,Math.floor(oy+(y+.5)/factor))*256+Math.min(255,Math.floor(ox+(x+.5)/factor))];dem.sourceZoom=parent.sourceZoom??parentCoords.z;return dem}
async function terrain(coords,signal){const key=coords.z+'/'+coords.x+'/'+coords.y;if(tileCache.has(key)){const value=tileCache.get(key);tileCache.delete(key);tileCache.set(key,value);return value}if(inflight.has(key))return inflight.get(key);const url=c=>'https://s3.amazonaws.com/elevation-tiles-prod/terrarium/'+c.z+'/'+c.x+'/'+c.y+'.png';const task=(async()=>{let dem;if(coords.z<=2){dem=tileGlobalData(coords);dem.sourceZoom=2}else{try{dem=await loadDem(coords,signal);dem.sourceZoom=coords.z}catch(error){if(error.name==='AbortError')throw error;let parent=null,parentCoords=null;for(let z=coords.z-1;z>=3;z--){const factor=2**(coords.z-z),c={z,x:Math.floor(coords.x/factor),y:Math.floor(coords.y/factor)},cached=tileCache.get(c.z+'/'+c.x+'/'+c.y);if(cached){parent=cached;parentCoords=c;break}}
if(!parent&&coords.z>3){parentCoords={z:coords.z-1,x:Math.floor(coords.x/2),y:Math.floor(coords.y/2)};parent=await loadDem(parentCoords,signal);parent.sourceZoom=parentCoords.z;tileCache.set(parentCoords.z+'/'+parentCoords.x+'/'+parentCoords.y,parent)}if(!parent)throw error;dem=tileFromParent(parent,coords,parentCoords);tileErrors++}}
if(coords.z>3){const candidates=DeepTerraTerrainQuality.suspects(dem);if(candidates.length){const parentCoords={z:coords.z-1,x:Math.floor(coords.x/2),y:Math.floor(coords.y/2)};try{const parent=await terrain(parentCoords,signal);DeepTerraTerrainQuality.repair(dem,parent,coords,parentCoords,candidates);}catch(error){if(error.name==='AbortError')throw error;}}}
if(coords.z>=6)DeepTerraTerrainQuality.seams(dem,coords);tileCache.set(key,dem);while(tileCache.size>80)tileCache.delete(tileCache.keys().next().value);return dem})();inflight.set(key,task);try{return await task}finally{inflight.delete(key)}}
// Keep rapid zooms from competing with obsolete elevation downloads.
const terrainRequests=new Map(),terrainQueue=[];let terrainRunning=0,terrainTimer=null;
function terrainPriority(job){if(![...job.records].some(r=>r.live)||job.coords.z!==Math.min(TERRAIN_MAX_ZOOM,map.getZoom()))return -Infinity;const bounds=map.getPixelBounds(),scale=2**(job.coords.z-map.getZoom()),left=bounds.min.x*scale/256,right=bounds.max.x*scale/256,top=bounds.min.y*scale/256,bottom=bounds.max.y*scale/256,total=2**job.coords.z,cx=(left+right)/2,x=job.coords.x+Math.round((cx-job.coords.x-.5)/total)*total;const visible=x+1>left&&x<right&&job.coords.y+1>top&&job.coords.y<bottom;return (visible?100000:0)-Math.hypot(x+.5-cx,job.coords.y+.5-(top+bottom)/2)}
function refreshTerrainQueue(){clearTimeout(terrainTimer);for(const job of terrainRequests.values()){if(terrainPriority(job)!==-Infinity)continue;if(job.running)job.controller.abort();else{const i=terrainQueue.indexOf(job);if(i>=0)terrainQueue.splice(i,1);terrainRequests.delete(job.key);job.reject(new DOMException('Carga descartada','AbortError'))}}terrainTimer=setTimeout(pumpTerrainQueue,70)}
function pumpTerrainQueue(){terrainTimer=null;terrainQueue.sort((a,b)=>terrainPriority(b)-terrainPriority(a));while(terrainRunning<6&&terrainQueue.length){const job=terrainQueue.shift();if(terrainPriority(job)===-Infinity){terrainRequests.delete(job.key);job.reject(new DOMException('Carga descartada','AbortError'));continue}job.running=true;terrainRunning++;terrain(job.coords,job.controller.signal).then(job.resolve,job.reject).finally(()=>{terrainRunning--;if(terrainRequests.get(job.key)===job)terrainRequests.delete(job.key);if(!terrainTimer)terrainTimer=setTimeout(pumpTerrainQueue,0)})}}
function terrainForRecord(record){const coords=record.coords,key=coords.z+'/'+coords.x+'/'+coords.y;if(tileCache.has(key))return terrain(coords);const existing=terrainRequests.get(key);if(existing&&!existing.controller.signal.aborted){existing.records.add(record);return existing.promise}const job={key,coords,records:new Set([record]),controller:new AbortController(),running:false};job.promise=new Promise((resolve,reject)=>{job.resolve=resolve;job.reject=reject});terrainRequests.set(key,job);terrainQueue.push(job);clearTimeout(terrainTimer);terrainTimer=setTimeout(pumpTerrainQueue,70);return job.promise}
let workerPool=[],workerQueue=[],workerFailed=false,nextJob=0;
function dispatchWorkers(){if(workerFailed)return;for(const slot of workerPool){if(slot.job||!workerQueue.length)continue;workerQueue.sort((a,b)=>b.priority()-a.priority());const job=workerQueue.shift();slot.job=job;try{slot.worker.postMessage({id:job.id,dem:job.dem.buffer,spill:job.spill.buffer},[job.dem.buffer,job.spill.buffer])}catch(error){slot.job=null;job.reject(error)}}}
function createWorkers(){for(let i=0;i<2;i++){const slot={worker:new Worker('flood-worker.js?v=20261006-26'),job:null};slot.worker.onmessage=e=>{const job=slot.job;if(!job||job.id!==e.data.id)return;slot.job=null;if(e.data.error)job.reject(Error(e.data.error));else job.resolve({threshold:new Float32Array(e.data.threshold),sea:new Uint8Array(e.data.sea)});dispatchWorkers()};slot.worker.onerror=()=>{workerFailed=true;for(const s of workerPool){if(s.job)s.job.reject(Error('Worker unavailable'));s.worker.terminate()}for(const job of workerQueue)job.reject(Error('Worker unavailable'));workerPool=[];workerQueue=[]};workerPool.push(slot)}}
function solveTile(dem,spill,entry){if(workerFailed||typeof Worker==='undefined')return Promise.resolve(DeepTerraFlood.solve(dem,spill));try{if(!workerPool.length)createWorkers();return new Promise((resolve,reject)=>{workerQueue.push({id:++nextJob,dem:dem.slice(),spill,resolve,reject,priority:()=>!entry?2:entry.coords.z===Math.min(TERRAIN_MAX_ZOOM,map.getZoom())&&entry.records.size?2:entry.records.size?1:0});dispatchWorkers()})}catch(e){workerFailed=true;return Promise.resolve(DeepTerraFlood.solve(dem,spill))}}

let floodNetwork=null,gpuRenderer=null,visualDirty=false,visualRefreshPending=false;
function spillFor(record){const {coords,dem}=record,spill=new Float32Array(65536);for(let y=0;y<256;y++)for(let x=0;x<256;x++){const i=y*256+x,wi=pixelWorldIndex(coords,x,y);spill[i]=dem[i]<=0&&nearOcean(wi)?0:state.world.spill[wi]}return spill}
function requestVisualRefresh(){visualDirty=true;if(state.playing||visualRefreshPending)return;visualRefreshPending=true;requestAnimationFrame(()=>{visualRefreshPending=false;if(visualDirty){visualDirty=false;repaint()}})}
async function tileModel(record,dem=record.dem){if(!floodNetwork)floodNetwork=new DeepTerraFloodNetwork({solve:async(dem,spill,entry)=>{const backup=spill.slice();try{return await solveTile(dem,spill,entry)}catch(e){return DeepTerraFlood.solve(dem,backup)}},base:spillFor,onUpdate:r=>{requestVisualRefresh()}});await floodNetwork.attach(record,dem)}

function nearOcean(i){const x=i%WORLD,y=i/WORLD|0;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const yy=y+dy;if(yy>=0&&yy<WORLD&&state.world.sea[yy*WORLD+(x+dx+WORLD)%WORLD])return true}return false}
function currentLevel(){return state.height*state.progress}
function depthColor(depth){return depth<10?[103,232,249]:depth<50?[56,189,248]:depth<100?[59,130,246]:depth<500?[139,92,246]:depth<1000?[217,70,239]:[244,114,182]}
function paint(record){if(!record.live||!record.dem||!record.threshold||!state.ready)return;const ctx=record.canvas.getContext('2d'),im=record.imageData||(record.imageData=ctx.createImageData(256,256)),h=currentLevel(),t=state.progress;
im.data.fill(0);const shade=state.showRelief?DeepTerraVisuals.prepare(record):null;const wet=i=>record.sea[i]||h>record.threshold[i]+.00001;
for(let i=0;i<record.dem.length;i++){const x=i%256,y=i>>8;
if(state.showWater&&!record.sea[i]&&h>record.threshold[i]+.00001){const depth=Math.max(0,h-record.dem[i]),k=Math.min(1,depth/Math.max(1,state.height));let rgb=state.depthColors?depthColor(depth):[72-k*24,215-k*145,230],alpha=Math.min(220,115+80*t+Math.min(25,depth*3))*state.waterOpacity;
if(state.showContour){const coverage=(Number(wet(x?i-1:i))+Number(wet(x<255?i+1:i))+Number(wet(y?i-256:i))+Number(wet(y<255?i+256:i)))*.25;alpha*=.55+.45*coverage;if(state.showContour&&coverage<1){rgb=[255,235,153];alpha=245*(.7+.3*coverage)}}
for(let j=0;j<3;j++)im.data[i*4+j]=rgb[j];im.data[i*4+3]=alpha;
}else if(state.showWater&&record.sea[i]&&t>0){im.data[i*4]=28;im.data[i*4+1]=148;im.data[i*4+2]=190;im.data[i*4+3]=Math.round(t*35*state.waterOpacity)
}else if(state.showRelief&&!record.sea[i]){const light=(shade[i]-128)/255,rgb=light>0?[246,239,219]:[17,31,37];for(let j=0;j<3;j++)im.data[i*4+j]=rgb[j];im.data[i*4+3]=Math.abs(light)*255}}

ctx.putImageData(im,0,0)}
function updateProgressLabels(){$('time').value=(state.progress*100).toFixed(1);$('timeLabel').textContent=Math.round(state.progress*100)+' %';$('elapsed').textContent=format(state.progress*state.duration)+' / '+format(state.duration)+' s';$('level').textContent=format(currentLevel())+' m';$('progressLevel').textContent='+'+format(currentLevel())+' m'}
function visibleTiles(){const bounds=map.getPixelBounds(),zoom=map.getZoom();return Array.from(activeTiles).filter(r=>{if(!r.live)return false;const scale=2**(r.coords.z-zoom),left=bounds.min.x*scale/256,right=bounds.max.x*scale/256,top=bounds.min.y*scale/256,bottom=bounds.max.y*scale/256,total=2**r.coords.z,cx=(left+right)/2,x=r.coords.x+Math.round((cx-r.coords.x-.5)/total)*total;return x+1>left&&x<right&&r.coords.y+1>top&&r.coords.y<bottom})}
function repaint(){const records=visibleTiles();let drawn=false;if(gpuRenderer){try{drawn=gpuRenderer.render(records,state)}catch(e){gpuRenderer=null}}if(!drawn)for(const record of records)paint(record);updateProgressLabels();if(state.areaCurve){const area=state.areaCurve[Math.min(state.areaCurve.length-1,Math.max(0,Math.floor(currentLevel()*4)))];$('area').textContent=compactNumber(area);$('areaFull').textContent=area.toLocaleString('es-CL',{maximumFractionDigits:0})}if(selected)showInspection(selected);updateCursorInfo();window.dispatchEvent(new Event('deepterra:frame'))}

function updatePlayback(){$('play').disabled=!state.ready;setIcon($('playIcon'),state.playing?'Pause':state.progress>=1?'RotateCcw':'Play');$('play').setAttribute('aria-label',state.playing?'Pausar simulación':state.progress>=1?'Reiniciar simulación':'Reproducir simulación');$('play').setAttribute('aria-pressed',String(state.playing))}
function pause(){state.playing=false;if(animationId!==null)cancelAnimationFrame(animationId);animationId=null;updatePlayback()}
function continuePlayback(){if(!state.ready||state.playing)return;if(state.progress>=1)state.progress=0;state.playing=true;lastFrame=performance.now();lastPaint=0;updatePlayback();repaint();animationId=requestAnimationFrame(frame)}
function frame(now){if(!state.playing)return;state.progress=Math.min(1,state.progress+(now-lastFrame)/(state.duration*1000));lastFrame=now;const interval=1000/30,delta=now-lastPaint;if(delta>=interval-.35||state.progress===1){repaint();visualDirty=false;lastPaint+=Math.max(1,Math.floor((delta+.35)/interval))*interval}if(state.progress>=1)pause();else animationId=requestAnimationFrame(frame)}

const map=L.map('map',{zoomControl:false,attributionControl:false,minZoom:1,maxZoom:MAP_MAX_ZOOM,worldCopyJump:true,touchZoom:true,dragging:true,scrollWheelZoom:true,doubleClickZoom:true,keyboard:true,zoomSnap:1,inertia:true,maxBounds:[[-85.0511,-Infinity],[85.0511,Infinity]],maxBoundsViscosity:.75}).setView([0,0],2);
map.createPane('relief');map.getPane('relief').style.zIndex=190;map.createPane('flood');map.getPane('flood').style.zIndex=350;
const baseMap=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxNativeZoom:MAP_MAX_ZOOM,maxZoom:MAP_MAX_ZOOM,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> · elevación Mapzen / AWS',keepBuffer:2,updateWhenIdle:false,updateInterval:150});
// OpenStreetMap de base y respaldo de MapTiler (map-preview.js).
baseMap.addTo(map);
let fallbackLayer,floodLayer;const pendingTiles=new Set();let tileErrors=0,settleTimer=null;
function loadingStatus(){clearTimeout(settleTimer);if(pendingTiles.size)notify('Cargando terreno…',false,true);else{settleTimer=setTimeout(()=>{if(tileErrors){notify('Parte del detalle no está disponible; se usa elevación de menor resolución.',true);tileErrors=0}else $('status').hidden=true},400)}}
function initLayers(){const ReliefLayer=L.GridLayer.extend({createTile(coords){const c=makeCanvas(),context=c.getContext('2d');const total=2**coords.z,source=state.world.relief;context.imageSmoothingEnabled=true;context.drawImage(source,coords.x/total*WORLD,coords.y/total*WORLD,WORLD/total,WORLD/total,0,0,256,256);return c}});fallbackLayer=new ReliefLayer({pane:'relief',tileSize:256,maxNativeZoom:12,maxZoom:MAP_MAX_ZOOM,keepBuffer:2,updateWhenIdle:false,updateInterval:150}).addTo(map);
const FloodLayer=L.GridLayer.extend({createTile(coords,done){const c=makeCanvas(),record={canvas:c,coords,dem:null,revision:-1,live:true,provisional:true,done};c._deepterraRecord=record;
previewTile(record);activeTiles.add(record);pendingTiles.add(record);paintPreview(record);requestVisualRefresh();loadingStatus();
loadMapTerrain(record);return c}});floodLayer=new FloodLayer({pane:'flood',tileSize:256,maxNativeZoom:TERRAIN_MAX_ZOOM,maxZoom:MAP_MAX_ZOOM,keepBuffer:2,updateWhenIdle:false,updateWhenZooming:true,updateInterval:150}).addTo(map);floodLayer.on('tileunload',e=>{const r=e.tile._deepterraRecord;if(r){r.live=false;if(floodNetwork)floodNetwork.detach(r);activeTiles.delete(r);pendingTiles.delete(r);refreshTerrainQueue();requestVisualRefresh()}})}
async function loadMapTerrain(record){
 if(!record.live||record.loading)return;record.loading=true;pendingTiles.add(record);loadingStatus();
 try{const dem=await terrainForRecord(record);if(!record.live)return;await tileModel(record,dem);record.provisional=false;record.retryAt=0;}
 catch(error){if(!record.live)return;if(error.name==='AbortError'){record.retryAt=performance.now()+250;}else{tileErrors++;record.retryAt=performance.now()+5000;const dem=record.dem;await tileModel(record,dem);record.provisional=false;}}
 finally{record.loading=false;pendingTiles.delete(record);if(record.live&&!record.provisional&&record.done){paint(record);const done=record.done;record.done=null;done(null,record.canvas);}requestVisualRefresh();loadingStatus();}
}
function resumeMapTerrain(){for(const record of visibleTiles())if(record.coords.z===Math.min(TERRAIN_MAX_ZOOM,map.getZoom())&&record.live&&!record.loading&&(record.provisional||record.retryAt)&&performance.now()>=(record.retryAt||0))loadMapTerrain(record);}
