// Public bridge for the optional local 3D view. Both views use the same state
// and FloodNetwork; the drone never creates a second flooding simulation.
let droneMapHandlers=null;
window.DeepTerraDroneBridge={
 snapshot:()=>({ready:state.ready,height:state.height,duration:state.duration,progress:state.progress,level:currentLevel(),playing:state.playing,showWater:state.showWater,depthColors:state.depthColors,showContour:state.showContour,waterOpacity:state.waterOpacity}),
 pause,
 center:()=>({lat:map.getCenter().lat,lng:map.getCenter().lng}),
 mapPoint:(x,y)=>{const box=map.getContainer().getBoundingClientRect();return map.containerPointToLatLng([x-box.left,y-box.top])},
 lockMap:()=>{if(droneMapHandlers)return;droneMapHandlers=['dragging','touchZoom','doubleClickZoom','scrollWheelZoom','boxZoom','keyboard'].filter(key=>map[key]?.enabled());for(const key of droneMapHandlers)map[key].disable()},
 unlockMap:()=>{for(const key of droneMapHandlers||[])map[key].enable();droneMapHandlers=null},
 closePanels:()=>{setMenu(false);setFilter(false);closeOpacityControl();closeInspection();window.dispatchEvent(new Event('deepterra:close-panels'))},
 prepareMap:(point,zoom)=>map.setView(point,zoom,{animate:false}),
 refreshMap:()=>{map.invalidateSize({pan:false});repaint()},
 releaseDroneTerrain:records=>{for(const record of records){record.live=false;if(floodNetwork)floodNetwork.detach(record)}},
 loadDroneTerrain:async(coords,signal,onProgress)=>{
   const records=coords.map(coords=>({coords,dem:null,threshold:null,sea:null,live:true,drone:true}));
   let cursor=0,complete=0;
   const check=()=>{if(signal.aborted)throw new DOMException('Carga cancelada','AbortError')};
   try{
     await Promise.all(Array.from({length:Math.min(3,records.length)},async()=>{
       while(cursor<records.length){check();const record=records[cursor++];const dem=await terrain(record.coords,signal);check();if(!record.live)return;await tileModel(record,dem);check();if(onProgress)onProgress(++complete)}
     }));
     check();
     await new Promise((resolve,reject)=>{
       const abort=()=>finish(new DOMException('Carga cancelada','AbortError'));
       const timer=setTimeout(()=>finish(Error('La conexión del terreno tardó demasiado')),30000);
       const finish=error=>{clearTimeout(timer);signal.removeEventListener('abort',abort);error?reject(error):resolve()};
       signal.addEventListener('abort',abort,{once:true});
       floodNetwork.settled().then(()=>finish());
     });
     check();return records;
   }catch(error){for(const record of records){record.live=false;if(floodNetwork)floodNetwork.detach(record)}throw error}
 }
};

